    // ---- R2: deleting clips -----------------------------------------------

    /// R2: Delete/Backspace keys remove exactly the selected clips; an
    /// automation clip deletes too (asset survives); repeat presses and a
    /// stale selection after remove_asset_at must not panic.
    #[test]
    fn v18_delete_key_removes_clips_and_survives_abuse() {
        let mut app = headless_app("v18delkey");
        let ctx = egui::Context::default();
        frame_keys(&mut app, &ctx, vec![]);
        let kick = app.rack[0].files[0].path.clone();
        let a = app.ensure_asset(std::path::Path::new(&kick)).unwrap() as u32;
        app.arr.insert(0, 0, Clip::new(a, 0));
        app.arr.insert(0, 0, Clip::new(a, 96_000));
        // v35 R7: bind through the manager and SAVE (no eager asset).
        app.open_bound_auto(Some(1), crate::automation::TARGET_TRACK_VOL, 0.5);
        frame(&mut app, &ctx, vec![]);
        click_label(&mut app, &ctx, "Save as new asset + clip");
        frame(&mut app, &ctx, vec![]);
        let before = n_clips(&app);
        assert_eq!(
            before, 3,
            "2 audio clips + 1 automation clip: {}",
            app.status
        );
        app.select_one((0, 0, 1));
        frame_keys(
            &mut app,
            &ctx,
            vec![key_ev(egui::Key::Delete, Default::default())],
        );
        assert_eq!(
            n_clips(&app),
            before - 1,
            "Delete key removed the clip: {}",
            app.status
        );
        assert_eq!(
            clip_ids(&app).iter().filter(|(t, _, _, _)| *t == 0).count(),
            1,
            "the RIGHT clip went (index 1, not the first)"
        );
        let (at, ak, ac, _c) = clip_ids(&app)
            .into_iter()
            .find(|(_, _, _, c)| {
                app.assets
                    .get(c.asset as usize)
                    .is_some_and(|x| x.is_auto())
            })
            .expect("automation clip placed");
        let n_assets = app.assets.len();
        app.select_one((at, ak, ac));
        frame_keys(
            &mut app,
            &ctx,
            vec![key_ev(egui::Key::Backspace, Default::default())],
        );
        assert_eq!(
            n_clips(&app),
            before - 2,
            "Backspace deleted the automation clip"
        );
        assert_eq!(
            app.assets.len(),
            n_assets,
            "automation ASSET stays in the rack"
        );
        // A stray key with no selection must no-op, not delete "whatever".
        assert!(app.sel_clips.is_empty());
        frame_keys(
            &mut app,
            &ctx,
            vec![key_ev(egui::Key::Delete, Default::default())],
        );
        assert_eq!(n_clips(&app), before - 2);
        // remove_asset_at cleared the selection — later Delete is a no-op.
        app.select_one((0, 0, 0));
        app.remove_asset_at(a as usize);
        frame_keys(
            &mut app,
            &ctx,
            vec![key_ev(egui::Key::Delete, Default::default())],
        );
        assert!(app.sel_clips.is_empty());
    }

    /// v35 R4: glyph coverage probe. Every icon-ish codepoint this file
    /// ships as TEXT must render in egui's default font stack — anything
    /// else paints a hollow tofu box (the drum-pad mute/remove report).
    /// While this list has members, replace the glyph (drawn vector or
    /// ASCII text), never paper over the check.
    #[test]
    fn v35_glyph_coverage_probe() {
        // Every symbol the shipped UI can paint — the probe keeps this list
        // honest; CI fails if a new glyph lands without coverage (v35 R4).
        const GLYPHS: &str = "\u{00b7}\u{00d7}\u{2013}\u{2014}\u{2019}\u{201c}\u{201d}\u{2026}\u{2212}\u{221e}\u{2248}\u{2264}\u{2265}\u{25a0}\u{266a}\u{266b}";
        // One real app frame: the probe then checks the SAME font stack
        // the shipped UI paints with (custom fonts install on first run).
        let mut app = headless_app("v35glyphs");
        let ctx = egui::Context::default();
        frame(&mut app, &ctx, vec![]);
        let missing: Vec<String> = ctx.fonts_mut(|f| {
            let id = egui::FontId::proportional(13.0);
            GLYPHS
                .chars()
                .filter(|c| !f.has_glyph(&id, *c))
                .map(|c| format!("U+{:04X}", c as u32))
                .collect()
        });
        assert!(missing.is_empty(), "TOFU GLYPHS: {}", missing.join(" "));
    }
    /// v35 fix pin: a FLOATING (undocked) dynamic window must paint
    /// exactly once. The generic dock pass used to draw floats for every
    /// registry slot — including dynamic ones, whose owners draw their
    /// own chrome — so an open MIXER CHAIN painted two full windows per
    /// frame (head probe: body galley count 2).
    #[test]
    fn v35_float_window_paints_once() {
        let mut app = headless_app("v35dbl");
        let ctx = egui::Context::default();
        app.fx_window = Some(0);
        frame(&mut app, &ctx, vec![]);
        frame(&mut app, &ctx, vec![]);
        let raw = egui::RawInput {
            screen_rect: Some(egui::Rect::from_min_size(
                egui::Pos2::ZERO,
                egui::vec2(1440.0, 853.0),
            )),
            time: Some(test_time()),
            ..Default::default()
        };
        let out = ctx.run_ui(raw, |ui| app.ui_root(ui));
        let body = out
            .shapes
            .iter()
            .filter(|cs| {
                matches!(&cs.shape, egui::epaint::Shape::Text(t) if t.galley.text() == "Chain (top = first):")
            })
            .count();
        let title = out
            .shapes
            .iter()
            .filter(|cs| {
                matches!(&cs.shape, egui::epaint::Shape::Text(t) if t.galley.text().starts_with("MIXER CHAIN"))
            })
            .count();
        assert_eq!(body, 1, "floating chain body must paint ONCE");
        assert_eq!(title, 1, "floating chain title must paint ONCE");
    }

    /// v35 R5/R6 pin: the MIXER CHAIN window is a first-class dockable —
    /// it docks to an edge (body painted by the panel, owner skips its
    /// float), stacks with a primary panel on the same edge, floats out,
    /// and its close button clears the OWNER state (no zombie registry).
    #[test]
    fn v35_chain_window_docks_and_stacks() {
        let mut app = headless_app("v35dock");
        let ctx = egui::Context::default();

        // v39: MASTER OUT docks on the right by default and is a
        // layout change these older geometry pins predate; close it.
        app.show_master = false;
        app.fx_window = Some(0);
        frame(&mut app, &ctx, vec![]);
        let idx = 4; // first dynamic slot
        assert_eq!(win_count(&app), 5, "chain window registered");
        assert!(!is_docked(&app, idx), "starts floating");

        // Dock right, then frame: the panel owns the body this frame.
        dock_at(&mut app, idx, 1, egui::pos2(1380.0, 300.0));
        assert!(is_docked(&app, idx));
        frame(&mut app, &ctx, vec![]);
        let r = app.dock_rects[idx];
        assert!(r[2] > 8.0, "docked chain painted nothing");
        assert!(r[0] > 700.0, "docked on the RIGHT edge, got x={}", r[0]);
        // A re-tiled stack settles within a couple of frames (egui sizes
        // resizable panels from memory written the frame before).
        // A painted-text scanner (same evidence `galleys_all` gathers,
        // taken straight from the frame output).
        let painted = |app: &mut App, needle: &str| -> usize {
            let raw = egui::RawInput {
                screen_rect: Some(egui::Rect::from_min_size(
                    egui::Pos2::ZERO,
                    egui::vec2(1440.0, 853.0),
                )),
                time: Some(test_time()),
                ..Default::default()
            };
            let out = ctx.run_ui(raw, |ui| app.ui_root(ui));
            out.shapes
                .iter()
                .filter(|cs| {
                    if let egui::epaint::Shape::Text(t) = &cs.shape {
                        t.galley.text() == needle
                    } else {
                        false
                    }
                })
                .count()
        };
        frame(&mut app, &ctx, vec![]);
        assert_eq!(
            painted(&mut app, "Chain (top = first):"),
            1,
            "one shared body, painted once"
        );

        // Stack a primary panel on the SAME edge — re-order keeps both.
        app.show_mixer = true;
        dock_at(&mut app, 3, 1, egui::pos2(1380.0, 80.0));
        for _ in 0..4 {
            frame(&mut app, &ctx, vec![]);
            if app.dock_rects[3][2] > 8.0 && app.dock_rects[idx][2] > 8.0 {
                break;
            }
        }
        assert_ne!(dock_order(&app, idx), dock_order(&app, 3), "tiled apart");
        assert!(app.dock_rects[idx][2] > 8.0, "chain still painted");
        assert!(app.dock_rects[3][2] > 8.0, "mixer still painted");

        // TOP edge (R6: all four directions).
        dock_at(&mut app, idx, 3, egui::pos2(600.0, 8.0));
        frame(&mut app, &ctx, vec![]);
        assert_eq!(dock_edge(&app, idx), 3);
        assert!(app.dock_rects[idx][1] < 120.0, "top strip is at the top");

        // Float out, then close from the dock state: owner clears too.
        dock_at(&mut app, idx, 1, egui::pos2(1380.0, 300.0));
        set_visible(&mut app, idx, false);
        assert!(app.fx_window.is_none(), "close clears the OWNER flag");
        assert!(!win_visible(&app, idx), "no zombie window");
        frame(&mut app, &ctx, vec![]); // and frames cleanly
        drop(app);
        settle_plugin_drop();
    }

    /// v35: every dynamic window class joins the dock system. Per kind:
    /// registry slot, ONE shared body (painted once floating, once
    /// docked — the double-paint regression family), dock close clears
    /// the OWNER's own state, reopen reuses the slot at its edge.
    /// (MIXER CHAIN pins above; PARAMETERS needs a real plugin and rides
    /// the v23 wolf-shaper pin.)
    #[test]
    fn v35_all_window_classes_dock() {
        let painted = |ctx: &egui::Context, app: &mut App, needle: &str| -> usize {
            let raw = egui::RawInput {
                screen_rect: Some(egui::Rect::from_min_size(
                    egui::Pos2::ZERO,
                    egui::vec2(1440.0, 853.0),
                )),
                time: Some(test_time()),
                ..Default::default()
            };
            let mut out = ctx.run_ui(raw, |ui| app.ui_root(ui));
            let n = out
                .shapes
                .iter()
                .filter(|cs| {
                    matches!(&cs.shape, egui::epaint::Shape::Text(t) if t.galley.text() == needle)
                })
                .count();
            out.textures_delta.clear();
            n
        };
        let mut app = headless_app("v35dockall");
        let ctx = egui::Context::default();

        // v39: MASTER OUT docks on the right by default and is a
        // layout change these older geometry pins predate; close it.
        app.show_master = false;
        // ---- DRUM MACHINE (slot 4) ----
        app.show_drums = true;
        frame(&mut app, &ctx, vec![]);
        assert_eq!(win_count(&app), 5, "drums slot registered");
        assert!(!is_docked(&app, 4), "starts floating like the chain window");
        assert_eq!(
            painted(&ctx, &mut app, "sixteenth note (4/beat)"),
            1,
            "floating drums paint their body exactly once"
        );
        dock_at(&mut app, 4, 1, egui::pos2(1380.0, 300.0));
        frame(&mut app, &ctx, vec![]);
        frame(&mut app, &ctx, vec![]);
        assert!(app.dock_rects[4][2] > 8.0, "docked drums painted");
        assert_eq!(
            painted(&ctx, &mut app, "sixteenth note (4/beat)"),
            1,
            "no owner ghost next to the docked body"
        );
        set_visible(&mut app, 4, false);
        assert!(!app.show_drums, "dock close clears show_drums");
        frame(&mut app, &ctx, vec![]);
        app.show_drums = true; // reopen: SAME slot, still at its edge
        frame(&mut app, &ctx, vec![]);
        frame(&mut app, &ctx, vec![]);
        assert_eq!(win_count(&app), 5, "slot reused on reopen");
        assert!(app.dock_rects[4][2] > 8.0, "reopens docked");
        set_visible(&mut app, 4, false);

        // ---- PIANO ROLL (slot 5): the take/restore family ----
        app.piano_roll = Some(Box::new(PianoRoll {
            pat: Pattern::new(120),
            px_per_beat: 90.0,
            row_h: 11.0,
            vscroll_px: 0.0,
            scroll_sec: 0.0,
            changed: false,
            gesture: RollGesture::None,
            canvas_rect: None,
            new_vel: 100,
            sel_notes: Vec::new(),
            sel_anchor: None,
            drag_notes: Vec::new(),
            focused: false,
            win_rect: None,
            edit_asset: None,
        }));
        frame(&mut app, &ctx, vec![]);
        assert_eq!(win_count(&app), 6, "roll slot registered");
        assert_eq!(painted(&ctx, &mut app, "preview:"), 1, "floating roll once");
        dock_at(&mut app, 5, 0, egui::pos2(80.0, 300.0));
        frame(&mut app, &ctx, vec![]);
        frame(&mut app, &ctx, vec![]);
        assert!(app.dock_rects[5][2] > 8.0, "docked roll painted");
        assert_eq!(
            painted(&ctx, &mut app, "preview:"),
            1,
            "no owner ghost next to the docked roll"
        );
        assert!(
            app.piano_roll.as_ref().unwrap().canvas_rect.is_some(),
            "the docked roll paints its canvas (body runs identically)"
        );
        // Float out: state survives the transition.
        undock_to(&mut app, 5, [300.0, 220.0]);
        frame(&mut app, &ctx, vec![]);
        frame(&mut app, &ctx, vec![]);
        assert!(!is_docked(&app, 5), "undocked");
        assert!(app.piano_roll.is_some(), "buffer survives undock");
        set_visible(&mut app, 5, false);
        assert!(app.piano_roll.is_none(), "dock close kills the roll");

        // ---- Automation manager (slot 6) ----
        app.open_auto_editor(None);
        frame(&mut app, &ctx, vec![]);
        assert_eq!(win_count(&app), 7, "automation slot registered");
        assert_eq!(
            painted(&ctx, &mut app, "target"),
            1,
            "floating manager paints once"
        );
        dock_at(&mut app, 6, 2, egui::pos2(600.0, 800.0));
        frame(&mut app, &ctx, vec![]);
        frame(&mut app, &ctx, vec![]);
        assert!(app.dock_rects[6][3] > 8.0, "docked manager painted");
        assert_eq!(painted(&ctx, &mut app, "target"), 1, "no ghost");
        set_visible(&mut app, 6, false);
        assert!(app.auto_edit.is_none(), "dock close discards the buffer");

        // ---- SYNTHS picker (slot 7) ----
        app.synth_pick = Some(0);
        frame(&mut app, &ctx, vec![]);
        assert_eq!(win_count(&app), 8, "picker slot registered");
        assert_eq!(
            painted(&ctx, &mut app, "Synthesizers (click binds to this track):"),
            1,
            "floating picker paints once"
        );
        dock_at(&mut app, 7, 3, egui::pos2(600.0, 8.0));
        frame(&mut app, &ctx, vec![]);
        frame(&mut app, &ctx, vec![]);
        assert!(app.dock_rects[7][2] > 8.0, "picker painted on the top edge");
        set_visible(&mut app, 7, false);
        assert_eq!(app.synth_pick, None, "dock close clears the picker owner");

        // ---- Script-synth sliders (slot 8) ----
        app.set_track_synth_stem(0, "sampler");
        app.synth_win = Some(0);
        frame(&mut app, &ctx, vec![]);
        assert_eq!(win_count(&app), 9, "sliders slot registered");
        assert!(!is_docked(&app, 8), "starts floating");
        dock_at(&mut app, 8, 1, egui::pos2(1380.0, 90.0));
        frame(&mut app, &ctx, vec![]);
        frame(&mut app, &ctx, vec![]);
        assert!(app.dock_rects[8][2] > 8.0, "docked sliders painted");
        set_visible(&mut app, 8, false);
        assert_eq!(app.synth_win, None, "dock close clears synth_win");
        frame(&mut app, &ctx, vec![]); // and frames cleanly
        drop(app);
        settle_plugin_drop();
    }

    /// v35: the DOCK GESTURE for dynamic windows — press on a floating
    /// sub-window's title bar carries it, the blue snap-zone outline
    /// paints while the pointer is in an edge zone, release docks. The
    /// registry-level pins above use `dock_at` directly and cannot see
    /// a broken arm/preview/release chain (the exact user-reported
    /// failure: no outline, no dock for the new classes).
    #[test]
    fn v35_drag_dyn_window_snaps_and_docks() {
        let mut app = headless_app("v35dragdyn");
        let ctx = egui::Context::default();
        app.show_drums = true;
        frame(&mut app, &ctx, vec![]);
        let wr = app.dyn_wins[0].rect;
        assert!(wr[2] > 8.0, "floating drums recorded their rect");

        // Press the DRUM MACHINE title bar.
        let from = galley_at(&mut app, &ctx, "drum machine")
            .expect("drum machine title visible")
            .center();
        frame(&mut app, &ctx, vec![moved(from)]);
        frame(
            &mut app,
            &ctx,
            vec![moved(from), btn(from, egui::PointerButton::Primary, true)],
        );
        assert_eq!(
            app.free_drag.map(|(i, _)| i),
            Some(4),
            "press on a dynamic window title arms the carry"
        );

        // Mid-air over the right zone: the predicted-slot ghost must paint
        // (v44 R2: it is the ONLY overlay — the full-edge band highlight
        // was removed, so the assertion targets the ghost's color).
        let dst = egui::pos2(1380.0, 400.0);
        frame(&mut app, &ctx, vec![moved(from + (dst - from) * 0.5)]);
        let raw = egui::RawInput {
            screen_rect: Some(egui::Rect::from_min_size(
                egui::Pos2::ZERO,
                egui::vec2(1440.0, 853.0),
            )),
            time: Some(test_time()),
            events: vec![moved(dst)],
            ..Default::default()
        };
        let mut out = ctx.run_ui(raw, |ui| app.ui_root(ui));
        // egui 0.36: rect_stroke tessellates as a stroked RectShape.
        let blue = out.shapes.iter().any(|cs| {
            matches!(&cs.shape, egui::epaint::Shape::Rect(r)
                if r.stroke.color == egui::Color32::from_rgb(150, 215, 255))
        });
        let prims = ctx.tessellate(std::mem::take(&mut out.shapes), out.pixels_per_point);
        drop(prims);
        out.textures_delta.clear();
        assert!(blue, "predicted-slot ghost paints during the carry");

        // Release inside the zone: docked.
        frame(
            &mut app,
            &ctx,
            vec![moved(dst), btn(dst, egui::PointerButton::Primary, false)],
        );
        assert!(is_docked(&app, 4), "release in the right zone docks");
        assert_eq!(dock_edge(&app, 4), 1, "docked to the RIGHT edge");
        drop(app);
        settle_plugin_drop();
    }

    /// v35 R8: deletion torture. Every delete path in the app, hammered in
    /// the orders a user actually produces, with frames (paint! engine
    /// sync!) in between: clip delete by key, remove_asset_at first /
    /// middle / last while its clips are placed AND while the automation
    /// manager and piano roll are open on neighbouring ids, select-all
    /// delete, clear_track under an open selection, delete with the rack
    /// selection pointing past the end. Must never panic, and every clip's
    /// asset id must stay in bounds after every step.
    #[test]
    fn v35_delete_torture_all_paths() {
        fn invariant(app: &App, step: &str) {
            let n = app.assets.len();
            for tr in app.arr.tracks.iter() {
                for ln in tr.lanes.iter() {
                    for c in ln.clips.iter() {
                        assert!(
                            (c.asset as usize) < n,
                            "{step}: clip asset id {} out of bounds ({} assets)",
                            c.asset,
                            n
                        );
                    }
                }
            }
        }
        let mut app = headless_app("v35deltorture");
        let ctx = egui::Context::default();
        clear_canvas(&mut app);
        let a0 = push_v20_audio(&mut app, "d0", 96_000);
        let a1 = push_v20_audio(&mut app, "d1", 48_000);
        let a2 = push_v20_audio(&mut app, "d2", 12_000);
        app.assets.push(crate::assets::Asset::midi(
            app.assets.len() as u32,
            "d3".into(),
            std::path::PathBuf::from("/tmp/d3-v35.mid"),
            {
                let mut q = Pattern::new(120);
                q.len_ticks = 4 * PPQ as u32;
                q.into()
            },
            false,
        ));
        let a3 = (app.assets.len() - 1) as u32;
        app.arr.insert(1, 0, Clip::new(a0, 0));
        app.arr.insert(1, 0, Clip::new(a1, 96_000));
        app.arr.insert(2, 0, Clip::new(a2, 0));
        app.arr.insert(2, 1, Clip::new(a3, 48_000));
        frame(&mut app, &ctx, vec![]);
        invariant(&app, "setup");

        // (1) Clip delete by Delete key with a stale extra id in the
        // selection (as if another clip had already been removed).
        app.sel_clips = vec![(1, 0, 0), (1, 0, 1), (1, 0, 9)];
        frame_keys(
            &mut app,
            &ctx,
            vec![key_ev(egui::Key::Delete, Default::default())],
        );
        frame(&mut app, &ctx, vec![]);
        invariant(&app, "after Delete key with stale id");

        // (2) Automation manager open on an auto asset; delete the asset
        // BEFORE it (id shift) and its own asset (editor must close).
        app.open_bound_auto(Some(1), crate::automation::TARGET_MASTER_TEMPO, 120.0);
        frame(&mut app, &ctx, vec![]);
        click_label(&mut app, &ctx, "Save as new asset + clip");
        frame(&mut app, &ctx, vec![]);
        let auto_id = app.assets.len() - 1;
        app.arr
            .insert(1, 0, crate::arrange::Clip::new(auto_id as u32, 0));
        frame(&mut app, &ctx, vec![]);
        app.open_bound_auto(Some(1), crate::automation::TARGET_MASTER_TEMPO, 120.0);
        frame(&mut app, &ctx, vec![]);
        click_label(&mut app, &ctx, "Save as new asset + clip");
        frame(&mut app, &ctx, vec![]);
        let auto2 = app.assets.len() - 1;
        // A manager opened ON an existing curve (toolbar button on a
        // selected auto clip) — "Save as new" leaves asset=None, so model
        // the opened-on-existing state directly.
        app.auto_edit.as_mut().unwrap().asset = Some(auto2);
        // delete the FIRST auto asset while the manager sits on the second
        app.remove_asset_at(auto_id);
        frame(&mut app, &ctx, vec![]);
        invariant(&app, "after removing the earlier auto asset");
        assert_eq!(
            app.auto_edit.as_ref().map(|e| e.asset),
            Some(Some(auto2 - 1)),
            "manager id shifted, editor stays open"
        );
        // now delete the manager's own asset: the editor closes with it
        app.remove_asset_at(app.auto_edit.as_ref().unwrap().asset.unwrap());
        frame(&mut app, &ctx, vec![]);
        assert!(app.auto_edit.is_none(), "manager closed with its asset");
        invariant(&app, "after removing the open auto asset");

        // (3) Piano roll open, delete the FIRST asset (id shift) and then
        // the roll's own asset (roll closes with it).
        app.piano_roll = Some(Box::new(PianoRoll {
            pat: Pattern::new(120),
            px_per_beat: 90.0,
            row_h: 11.0,
            vscroll_px: 396.0,
            scroll_sec: 0.0,
            changed: false,
            gesture: RollGesture::None,
            canvas_rect: None,
            new_vel: 100,
            sel_notes: Vec::new(),
            sel_anchor: None,
            drag_notes: Vec::new(),
            focused: true,
            win_rect: None,
            edit_asset: Some(a3),
        }));
        frame(&mut app, &ctx, vec![]);
        app.remove_asset_at(0);
        frame(&mut app, &ctx, vec![]);
        assert_eq!(app.piano_roll.as_ref().unwrap().edit_asset, Some(a3 - 1));
        app.remove_asset_at(app.piano_roll.as_ref().unwrap().edit_asset.unwrap() as usize);
        frame(&mut app, &ctx, vec![]);
        assert!(app.piano_roll.is_none(), "roll closed with its asset");
        invariant(&app, "after roll-bound removals");

        // (4) select-all + delete everything, then clear_track on top.
        app.select_all_clips();
        let had = !app.sel_clips.is_empty();
        app.delete_selection();
        frame(&mut app, &ctx, vec![]);
        assert!(had);
        for t in 0..4 {
            app.clear_track(t);
        }
        frame(&mut app, &ctx, vec![]);
        invariant(&app, "after select-all delete + clear_track");

        // (5) Rack selection pointing past the end after a removal — the
        // asset-window toolbar guards on k < len, but hammer it anyway.
        app.assets.clear();
        app.sel_asset = Some(99);
        frame(&mut app, &ctx, vec![]);
        invariant(&app, "empty asset table paints");
    }

    /// v35 R8: the reported repro itself — right-click the grid over a
    /// loaded track, take "Clear this track's clips", then keep painting.
    /// Variants: with a clip selected, with the automation manager open on
    /// one of the doomed clips, with the piano roll open, twice in a row,
    /// and the menu items that mutate (Delete/Duplicate) followed by a
    /// later item in the SAME menu pass.
    #[test]
    fn v35_clear_track_menu_repro() {
        let mut app = headless_app("v35cleardel");
        let ctx = egui::Context::default();
        clear_canvas(&mut app);
        let a0 = push_v20_audio(&mut app, "c0", 96_000);
        let a1 = push_v20_audio(&mut app, "c1", 48_000);
        app.arr.insert(1, 0, Clip::new(a0, 0));
        app.arr.insert(1, 0, Clip::new(a1, 96_000));
        frame(&mut app, &ctx, vec![]);
        let find = |app: &mut App, ctx: &egui::Context, label: &str| -> Option<egui::Pos2> {
            label_center(app, ctx, label)
        };
        // A point inside track 1's (internal index 1… tracks are internal)
        // parent-lane strip: sweep rows until the grid menu opens.
        let mut opened = false;
        let kick_x = {
            let rr = app.ruler_rect.expect("ruler");
            (rr.min.x + 10.0, rr.center().y)
        };
        for dy in [10.0, 30.0, 50.0, 80.0, 110.0, 140.0, 170.0, 210.0, 250.0] {
            let p = egui::pos2(kick_x.0, kick_x.1 + dy);
            rmb(&mut app, &ctx, p);
            frame(&mut app, &ctx, vec![]);
            if find(&mut app, &ctx, "Clear this track's clips").is_some() {
                opened = true;
                break;
            }
        }
        assert!(opened, "grid right-click menu with a Clear item must open");
        let cp = find(&mut app, &ctx, "Clear this track's clips").unwrap();
        frame(&mut app, &ctx, vec![moved(cp)]);
        frame(
            &mut app,
            &ctx,
            vec![moved(cp), btn(cp, egui::PointerButton::Primary, true)],
        );
        frame(
            &mut app,
            &ctx,
            vec![moved(cp), btn(cp, egui::PointerButton::Primary, false)],
        );
        frame(&mut app, &ctx, vec![]);
        assert!(app.status.contains("cleared"), "{}", app.status);
        // Clips gone, assets stay, no panic. Repeat immediately.
        let n = app.assets.len();
        assert_eq!(n, 2);
        for _ in 0..3 {
            frame(&mut app, &ctx, vec![]);
        }
    }

    // ---- R3: automation creation by right-click ----------------------------

    /// R3a: right-clicking the BPM box opens the mini menu; "Create
    /// automation clip" opens the manager BOUND (v35 R7: nothing is
    /// created until the manager saves); saving produces an AUTO asset +
    /// clip at the playhead on the owning track, and a second creation
    /// gets its own asset (automation-2, never overwritten).
    #[test]
    fn v18_rmb_tempo_creates_automation_asset_twice() {
        let mut app = headless_app("v18rmbtempo");
        let ctx = egui::Context::default();
        frame(&mut app, &ctx, vec![]);
        let n0 = app.assets.len();
        let p = app.bpm_rect.expect("bpm rect painted").center();
        rmb(&mut app, &ctx, p);
        click_label(&mut app, &ctx, "Create automation clip");
        // v35 R7: binding creates NOTHING until the manager saves.
        frame(&mut app, &ctx, vec![]);
        assert_eq!(app.assets.len(), n0, "no eager asset: {}", app.status);
        assert!(app.auto_edit.is_some(), "manager open on the bound curve");
        assert_eq!(
            app.auto_edit.as_ref().unwrap().target,
            crate::automation::TARGET_MASTER_TEMPO
        );
        click_label(&mut app, &ctx, "Save as new asset + clip");
        frame(&mut app, &ctx, vec![]);
        assert_eq!(
            app.assets.len(),
            n0 + 1,
            "AUTO asset on save: {}",
            app.status
        );
        assert!(app.assets[n0].is_auto(), "kind = automation");
        let ids = clip_ids(&app);
        assert_eq!(ids.len(), 1, "automation clip placed: {}", app.status);
        assert_eq!(ids[0].0, 0, "placed on the selected track");
        assert_eq!(app.assets[n0].name, "automation");
        // Second creation: its own asset, never overwrite the first. The
        // rect is re-read because the top bar's layout belongs to the app
        // (a v18 pin — it used to JITTER with status text; a real user
        // aims at the CURRENTLY painted box).
        let p = app.bpm_rect.expect("bpm rect still painted").center();
        rmb(&mut app, &ctx, p);
        click_label(&mut app, &ctx, "Create automation clip");
        click_label(&mut app, &ctx, "Save as new asset + clip");
        frame(&mut app, &ctx, vec![]);
        assert_eq!(app.assets.len(), n0 + 2, "second asset: {}", app.status);
        assert_eq!(
            app.assets[n0 + 1].name,
            "automation-2",
            "automation-2 next to automation"
        );
    }

    /// R3a-2 (v20 R3 restated by v35 R7): right-clicking a TRACK volume
    /// readout in the mixer opens the value MENU (no asset yet); the
    /// automation item opens the manager bound to THAT track's volume and
    /// the save lands the asset/clip on that track.
    #[test]
    fn v18_rmb_track_vol_creates_auto_for_that_target() {
        let mut app = headless_app("v18rmbvol");
        let ctx = egui::Context::default();
        frame(&mut app, &ctx, vec![]);
        // Paint order in the mixer: master strip first, then track 1.
        let readout = format!("{:>5}", db_num(1.0));
        let hits = galleys_all(&mut app, &ctx, &readout);
        let p = *hits
            .get(1)
            .unwrap_or_else(|| panic!("expected master + track-1 dB readouts, got {hits:?}"));
        let n0 = app.assets.len();
        rmb(&mut app, &ctx, p);
        frame(&mut app, &ctx, vec![]);
        assert_eq!(
            app.assets.len(),
            n0,
            "right-click opens a MENU now: {}",
            app.status
        );
        assert!(app.value_menu.is_some(), "value menu open");
        click_label(&mut app, &ctx, "Create automation clip");
        frame(&mut app, &ctx, vec![]);
        assert_eq!(app.assets.len(), n0, "still nothing created until save");
        let ed = app.auto_edit.as_ref().expect("manager opened bound");
        assert_eq!(ed.target, crate::automation::TARGET_TRACK_VOL);
        assert_eq!(ed.asset, None, "unsaved curve");
        assert_eq!(
            ed.host,
            Some(1),
            "bound to the track it rides (strips are master + tracks 1..n)"
        );
        click_label(&mut app, &ctx, "Save as new asset + clip");
        frame(&mut app, &ctx, vec![]);
        assert_eq!(app.assets.len(), n0 + 1, "save creates: {}", app.status);
        let auto = app.assets[n0]
            .automation
            .as_ref()
            .expect("automation attached");
        assert_eq!(auto.target, crate::automation::TARGET_TRACK_VOL);
    }

    // ---- v20 R3: right-click = DIRECT automation clip creation -----------

    fn push_v20_audio(app: &mut App, name: &str, frames: usize) -> u32 {
        let data: std::sync::Arc<[f32]> = vec![0.25f32; frames].into();
        let a = app.assets.len() as u32;
        app.assets.push(crate::assets::Asset::audio(
            a,
            name.into(),
            std::path::PathBuf::from(format!("/tmp/{name}-v20.wav")),
            data,
            false,
        ));
        a
    }

    /// Track-1 volume readout center. Callers FIRST set `trk_vol[0]` to a
    /// value the rest of the mixer does not show — then exactly one widget
    /// paints that dB string, and the hit cannot be confused with master.
    fn v20_track1_vol_point(app: &mut App, ctx: &egui::Context) -> egui::Pos2 {
        let readout = format!("{:>5}", db_num(vol_amp(app.trk_vol[0])));
        let hits = galleys_all(app, ctx, &readout);
        assert_eq!(
            hits.len(),
            1,
            "track-1 readout {:?} must be painted exactly once, got {hits:?}",
            readout
        );
        hits[0]
    }

    fn v20_master_vol_point(app: &mut App, ctx: &egui::Context) -> egui::Pos2 {
        let want = format!("{:>5}", db_num(vol_amp(app.master_midi)));
        label_center(app, ctx, &want)
            .unwrap_or_else(|| panic!("master dB readout {:?} not painted", want))
    }

    fn v20_placed(app: &App, asset: u32) -> Option<(usize, usize, crate::arrange::Clip)> {
        (0..MAX_LOOPS).find_map(|t| {
            app.arr.tracks[t]
                .lanes
                .iter()
                .enumerate()
                .find_map(|(l, ln)| {
                    ln.clips
                        .iter()
                        .find(|c| c.asset == asset)
                        .cloned()
                        .map(|c| (t, l, c))
                })
        })
    }

    /// R3 (v35 R7 restatement): right-clicking the track-volume readout
    /// opens the value MENU (NO direct creation); the automation item
    /// opens the manager bound FLAT at the control's current value on the
    /// OWNER track, and only the manager's save places asset + clip.
    #[test]
    fn v20_rmb_slider_creates_auto_clip() {
        let mut app = headless_app("v20rmbauto1");
        let ctx = egui::Context::default();
        clear_canvas(&mut app);
        app.set_trk_vol(0, 32); // strip 1 must read differently from master
        frame(&mut app, &ctx, vec![]);
        let p = v20_track1_vol_point(&mut app, &ctx);
        let n0 = app.assets.len();
        rmb(&mut app, &ctx, p);
        frame(&mut app, &ctx, vec![]);
        assert_eq!(
            app.assets.len(),
            n0,
            "RMB alone creates nothing: {}",
            app.status
        );
        assert!(app.value_menu.is_some(), "mini menu at the pointer");
        click_label(&mut app, &ctx, "Create automation clip");
        frame(&mut app, &ctx, vec![]);
        assert_eq!(app.assets.len(), n0, "binding still creates nothing");
        let ed = app.auto_edit.as_ref().expect("manager opened bound");
        assert_eq!(ed.asset, None, "unsaved bound curve");
        assert_eq!(ed.target, crate::automation::TARGET_TRACK_VOL);
        assert_eq!(ed.host, Some(0), "host = the strip that was right-clicked");
        let cur = vol_amp(app.trk_vol[0]);
        assert!(
            ed.nodes.iter().all(|n| (n.v - cur).abs() < 1e-6),
            "curve seeded FLAT at the current value (no jump): {:?}",
            ed.nodes.iter().map(|n| n.v).collect::<Vec<_>>()
        );
        // Empty project → the documented 2 s fallback length.
        assert_eq!(ed.len_samples as u64, 48_000 * 2);
        park_window(&mut app, &ctx, "Automation", egui::vec2(0.0, -220.0));
        click_label(&mut app, &ctx, "Save as new asset + clip");
        frame(&mut app, &ctx, vec![]);
        assert_eq!(
            app.assets.len(),
            n0 + 1,
            "save creates the asset: {}",
            app.status
        );
        let (t, _lane, cl) = v20_placed(&app, n0 as u32).expect("automation clip placed");
        assert_eq!(t, 0, "clip on the OWNER track");
        assert_eq!(cl.pos, 0, "no selection → snapped playhead");
    }

