    /// R4c: after a REAL click on track 3's grid, Ctrl+V lands on track 3.
    #[test]
    fn v18_paste_lands_on_last_clicked_track() {
        let mut app = headless_app("v18pastetgt");
        let ctx = egui::Context::default();

        // v39: MASTER OUT docks on the right by default and is a
        // layout change these older geometry pins predate; close it.
        app.show_master = false;
        frame_keys(&mut app, &ctx, vec![]);
        let kick = app.rack[0].files[0].path.clone();
        let a = app.ensure_asset(std::path::Path::new(&kick)).unwrap() as u32;
        app.arr.insert(0, 0, Clip::new(a, 48_000));
        app.select_one((0, 0, 0));
        frame_keys(
            &mut app,
            &ctx,
            vec![
                egui::Event::ModifiersChanged(egui::Modifiers::COMMAND),
                key_ev(egui::Key::C, egui::Modifiers::COMMAND),
            ],
        );
        // Real left-click on track 3's EMPTY grid area: x sits in the
        // stable span between the clip's right edge (~510 px at 160 px/s)
        // and the strip control cluster (which is right-anchored and moves
        // as strip content grows — pins at 1100 broke twice on that).
        // Settle a frame first so the props-strip shift is baked into
        // grid_anchor before geometry is sampled.
        frame(&mut app, &ctx, vec![]);
        let top3 = app.grid_anchor - app.vscroll + 2.0 * (app.track_h(2) + TRACK_SEP_HIT);
        let p = egui::pos2(800.0, top3 + app.track_h(2) * 0.5);
        frame(&mut app, &ctx, vec![moved(p)]);
        frame(
            &mut app,
            &ctx,
            vec![moved(p), btn(p, egui::PointerButton::Primary, true)],
        );
        frame(
            &mut app,
            &ctx,
            vec![btn(p, egui::PointerButton::Primary, false)],
        );
        assert_eq!(
            app.last_click_track,
            Some(2),
            "grid click remembered track 3"
        );
        frame_keys(
            &mut app,
            &ctx,
            vec![
                egui::Event::ModifiersChanged(egui::Modifiers::COMMAND),
                key_ev(egui::Key::V, egui::Modifiers::COMMAND),
            ],
        );
        let ids = clip_ids(&app);
        assert_eq!(ids.len(), 2);
        assert!(
            ids.iter().any(|(t, _, _, _)| *t == 2),
            "paste landed on track 3: {ids:?}"
        );
    }

